```ts
function surfaceMs(store, runs) {
  let minted = 0;
  const port = createAffordancePort({ mintId: () => `c-${++minted}`, projectId: PROJECT_ID, store });
  const start = performance.now();
  for (let i = 0; i < runs; i += 1) port.readSurface();
  return (performance.now() - start) / runs;
}
const store = openStore(); driveThrough(store, "goal.close");
LOG("SURFACE_MS_UNLANDED", surfaceMs(store, 20));
seedReviewAcceptance(store, "node-a"); seedLandingReceipt(store, "node-a", "COMMITTED");
LOG("SURFACE_MS_LANDED", surfaceMs(store, 20));
const folded = readDurableLedger(store, PROJECT_ID);
// per-goal cost
let t = performance.now();
for (let i = 0; i < 20; i += 1) goalHasLandedCommit(store, PROJECT_ID, GOAL_ID, folded);
LOG("FACT_MS_PER_GOAL", (performance.now() - t) / 20);
// grow the decision ledger, then re-measure: readReviewLedgers pages EVERY decision
for (let n = 0; n < 40; n += 1) {
  seedReviewAcceptance(store, `node-bulk-${n}`);
  seedLandingReceipt(store, `node-bulk-${n}`, "COMMITTED");
}
const grown = readDurableLedger(store, PROJECT_ID);
t = performance.now();
for (let i = 0; i < 20; i += 1) goalHasLandedCommit(store, PROJECT_ID, GOAL_ID, grown);
LOG("FACT_MS_PER_GOAL_GROWN", (performance.now() - t) / 20);
LOG("SURFACE_MS_GROWN", surfaceMs(store, 10));
// 20 goal questions: per-goal vs ONE shared reader
t = performance.now();
for (let g = 0; g < 20; g += 1) goalHasLandedCommit(store, PROJECT_ID, GOAL_ID, grown);
LOG("TWENTY_GOALS_PER_GOAL_MS", performance.now() - t);
t = performance.now();
const reader = createGoalLandingReader(store, PROJECT_ID, grown);
for (let g = 0; g < 20; g += 1) reader.hasLandedCommit(GOAL_ID);
LOG("TWENTY_GOALS_SHARED_MS", performance.now() - t);
```
